{
is_shown_when_inactive = { c:CHI ?= this NOT = { has_variable = ywc_chi_a_started } }
possible = { c:CHI ?= this is_country_alive = yes ywc_v03_has_capacity = yes NOT = { has_variable = ywc_chi_a_started } }
immediate = { ywc_chi_claim_arc_a = yes }
on_monthly_pulse = { effect = {
ywc_chi_claim_arc_a = yes
if = { limit = { ywc_chi_delivery_1000 = yes } trigger_event = { id = ywc_regional.1000 } }
if = { limit = { ywc_chi_delivery_1001 = yes } trigger_event = { id = ywc_regional.1001 } }
if = { limit = { ywc_chi_delivery_1002 = yes } trigger_event = { id = ywc_regional.1002 } }
} }
on_complete = { ywc_chi_release_arc_a = yes }
on_fail = { ywc_chi_release_arc_a = yes }
}

